package com.oracle.banking.branch.exception;import com.oracle.banking.shared.response.ErrorResponse;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.ConstraintViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<ErrorResponse>n(ResourceNotFoundException e,HttpServletRequest r){return x(HttpStatus.NOT_FOUND,e.getMessage(),r);}@ExceptionHandler(ConstraintViolationException.class)ResponseEntity<ErrorResponse>v(ConstraintViolationException e,HttpServletRequest r){return x(HttpStatus.BAD_REQUEST,"Invalid request",r);}@ExceptionHandler(Exception.class)ResponseEntity<ErrorResponse>g(Exception e,HttpServletRequest r){return x(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r);}private ResponseEntity<ErrorResponse>x(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(ErrorResponse.of(m,r.getRequestURI()));}}
